import unittest

import mylib as m


class T(unittest.TestCase):
    def test_average_hidden(self):
        self.assertEqual(m.average([5]), 5)
        self.assertEqual(m.average([-1, 1]), 0)

    def test_unique_sorted_hidden(self):
        self.assertEqual(m.unique_sorted([]), [])
        self.assertEqual(m.unique_sorted([5, 5]), [5])

    def test_count_vowels_hidden(self):
        self.assertEqual(m.count_vowels(''), 0)
        self.assertEqual(m.count_vowels('xyz'), 0)

    def test_total_hidden(self):
        self.assertEqual(m.total([]), 0)
        self.assertEqual(m.total([-1, 5]), 4)

    def test_factorial_hidden(self):
        self.assertEqual(m.factorial(0), 1)
        self.assertEqual(m.factorial(6), 720)

    def test_maximum_hidden(self):
        self.assertEqual(m.maximum([-5, -2, -9]), -2)
        self.assertEqual(m.maximum([7]), 7)

    def test_reverse_words_hidden(self):
        self.assertEqual(m.reverse_words('one'), 'one')
        self.assertEqual(m.reverse_words('x  y'), 'y x')


if __name__ == '__main__':
    unittest.main()
